-- Generated by themectl from theme {{theme}} ({{mode}}). Do not edit: change the theme file, run `themectl apply`.
--
-- Hyprland reads this twice: at start, through `pcall(require, "config/theme")` in hyprland.lua (after config/appearance, whose
-- own colours it overrides; guarded, so a missing file -- after `themectl restore` -- is not an error), and live, through
-- `hyprctl eval 'dofile("<this file>")'` every time themectl applies.
-- No `hyprctl reload`: that would drop the runtime binds, layer rules and handlers the shell installed.
local border_active = "{{hyprBorderActive|hex}}"
local border_inactive = "{{hyprBorderInactive|hex}}"
local border_group_locked = "{{hyprBorderLocked|hex}}"
local group_tab = "{{hyprGroupTab|hex}}"

hl.config({
    general = {
        col = {
            active_border = "rgb(" .. border_active .. ")",
            inactive_border = "rgb(" .. border_inactive .. ")"
        }
    },

    decoration = {
        shadow = {
            color = "rgba(" .. border_active .. "08)"
        }
    },

    group = {
        col = {
            border_active =             "rgb(" .. border_active .. ")",
            border_inactive =           "rgb(" .. border_inactive .. ")",
            -- a locked group's border is the plain border: the lock shows in its tab (hypr-group-tabs) / its bar
            border_locked_active =      "rgb(" .. border_active .. ")",
            border_locked_inactive =    "rgb(" .. border_inactive .. ")"
        },
        groupbar = {
            col = {
                active =            "rgb(" .. group_tab .. ")",
                inactive =          "rgb(" .. border_inactive .. ")",
                locked_active =     "rgb(" .. border_group_locked .. ")",
                locked_inactive =   "rgba(" .. border_inactive .. "CC)"
            }
        }
    }
})

-- Hyprglass (the plugin has its own light/dark: `plugin:hyprglass:default_theme`, which the old script wrote into plugins.lua).
-- Set here for a live apply, and again when a config reload ends: plugins.lua runs AFTER this file and its hg.config({ default_theme = ... })
-- would otherwise put its own (stale) value back -- the handler runs after the whole config is loaded, so it has the last word. The mode lives in
-- a global so a second dofile (every apply) only moves it; a reload starts a new Lua state, which registers the handler once more.
themectl_hyprglass_theme = "{{mode}}"
local function themectl_hyprglass_apply()
    if hl.plugin and hl.plugin.hyprglass then
        hl.config({ plugin = { hyprglass = { default_theme = themectl_hyprglass_theme } } })
    end
end
themectl_hyprglass_apply()
if not themectl_hyprglass_hooked then
    themectl_hyprglass_hooked = true
    hl.on("config.reloaded", themectl_hyprglass_apply)
end
